  boolean v25=Boolean.getBoolean("paletale.test.itemPackV25");String version=v25?"v25":"v24";String packName="smc-items-"+version+"-qa.zip";var nativeRows=new java.util.concurrent.atomic.AtomicBoolean(v25||Boolean.getBoolean("paletale.test.itemPackV24"));var imageCalls=new java.util.concurrent.atomic.AtomicInteger();var previousPacks=new java.util.concurrent.atomic.AtomicReference<java.util.Collection<String>>();var reloading=new java.util.concurrent.atomic.AtomicReference<java.util.concurrent.CompletableFuture<Void>>();
